<?php
$root = dirname( __DIR__ );
$main = file_get_contents( $root . '/contactpanda-business/contactpanda-business.php' );
$schema = file_get_contents( $root . '/contactpanda-business/includes/class-contactpanda-business-schema.php' );
$projects = file_get_contents( $root . '/contactpanda-business/includes/class-contactpanda-business-projects.php' );
$workspace = file_get_contents( $root . '/contactpanda-business/includes/class-contactpanda-business-workspace.php' );
$imports = file_get_contents( $root . '/contactpanda-business/includes/class-contactpanda-business-imports.php' );
$mcp = file_get_contents( $root . '/contactpanda-business/includes/class-contactpanda-business-mcp.php' );
$access = file_get_contents( $root . '/contactpanda-business/includes/class-contactpanda-business-access.php' );
foreach ( array( 'projects', 'participants', 'areas', 'tasks', 'comments', 'attachments', 'checklist', 'events', 'imports', 'import_items', 'project_steps', 'project_documents', 'payments' ) as $table ) if ( false === strpos( $schema, "'{$table}'" ) ) { fwrite( STDERR, "Missing table {$table}.\n" ); exit( 1 ); }
foreach ( array( 'business', 'project_management' ) as $module ) if ( false === strpos( $main, "'{$module}'" ) ) { fwrite( STDERR, "Missing module {$module}.\n" ); exit( 1 ); }
foreach ( array( 'Requires Plugins: contactpanda, contactpanda-pro', 'CONTACTPANDA_BUSINESS_MIN_PRO_VERSION', 'CONTACTPANDA_PRO_VERSION', 'ContactPanda_Pro_Access', "contactpanda_pro_module_entitled( 'pro' )", "add_action( 'plugins_loaded', 'contactpanda_business_boot', 50 )" ) as $dependency ) if ( false === strpos( $main, $dependency ) ) { fwrite( STDERR, "Missing Business-to-Pro dependency contract {$dependency}.\n" ); exit( 1 ); }
foreach ( array( 'customer_management', 'contract_management', 'subscription_management', 'payment_management' ) as $pro_module ) if ( false !== strpos( $main, "'{$pro_module}'" ) ) { fwrite( STDERR, "Pro module {$pro_module} must not remain registered by Business.\n" ); exit( 1 ); }
foreach ( array( 'ContactPanda_Business_Access', 'contactpanda_pro_capability_map', 'contactpanda_mcp_allowed', 'allow_mcp', 'contactpanda_projects_view', 'contactpanda_tasks_comment', 'contactpanda_project_imports_manage' ) as $contract ) if ( false === strpos( $access . $main, $contract ) ) { fwrite( STDERR, "Missing Business authorization bridge contract {$contract}.\n" ); exit( 1 ); }
foreach ( array( 'resource_context', 'owner_user_id', 'assigned_user_id', "ContactPanda_Business_Access::can( 'edit'", "ContactPanda_Business_Access::can( 'create'", "ContactPanda_Business_Access::audit" ) as $contract ) if ( false === strpos( $access . $projects . $workspace . $imports, $contract ) ) { fwrite( STDERR, "Missing resource authorization or audit contract {$contract}.\n" ); exit( 1 ); }
foreach ( array( $projects, $workspace, $imports ) as $protected_controller ) if ( false !== strpos( $protected_controller, "current_user_can( 'manage_options' )" ) ) { fwrite( STDERR, "Business controllers must use the shared authorization bridge instead of an administrator-only guard.\n" ); exit( 1 ); }
foreach ( array( 'open', 'in_progress', 'review', 'done', 'waiting_customer', 'due_at', 'visibility', 'move_task', 'The task could not be moved.', 'customer_task', 'customer_update_task', 'contactpanda_customer_portal_tabs', 'ContactPanda_Customer_Portal::tab_url', 'contactpanda_pro_ticket_sidebar', 'contactpanda_pro_customer_detail', 'customer_projects', 'Assigned projects', 'participant_role', 'access_level', 'Project color', 'Search participants', 'Project permissions', 'Edit project', 'project_participants', 'task_detail_modal', 'inline_task_form', 'upload_task_files', 'add_checklist_item', 'toggle_checklist_item', 'Comments & activity', 'General information', 'Tasks and corrections', 'save_project_step', 'upload_project_documents', 'save_project_payment', 'budget_total', 'financing_notes' ) as $contract ) if ( false === strpos( $projects . $schema, $contract ) ) { fwrite( STDERR, "Missing project contract {$contract}.\n" ); exit( 1 ); }
foreach ( array( 'pro_customer_id', 'pro_payment_id', 'pro_invoice_id', 'link_pro_customers', 'participant_pro_customer_id', 'Linked Pro invoice', 'contactpanda_business_project_payment_created' ) as $bridge ) if ( false === strpos( $projects . $schema, $bridge ) ) { fwrite( STDERR, "Missing Pro/Business bridge contract {$bridge}.\n" ); exit( 1 ); }
if ( false !== strpos( $main, 'class-contactpanda-business-updater.php' ) ) { fwrite( STDERR, "Business must use the updater centrally supplied by ContactPanda Basic.\n" ); exit( 1 ); }
foreach ( array( 'project_action', 'task_action', 'save_area', 'export_report', 'Move project to trash', 'Duplicate task', 'Word report' ) as $contract ) if ( false === strpos( $workspace, $contract ) ) { fwrite( STDERR, "Missing workspace contract {$contract}.\n" ); exit( 1 ); }
foreach ( array( 'stage_rows', 'Review imported tasks', 'match_task_id', 'Add as comment', 'Reopen completed task', 'archive_source', 'Bulk edit selected tasks', 'data-cpb-import-bulk', 'data-cpb-import-select-all', 'applied_at', 'apply_count', 'confirm_repeat', 'run this import again' ) as $contract ) if ( false === strpos( $imports . $schema, $contract ) ) { fwrite( STDERR, "Missing import contract {$contract}.\n" ); exit( 1 ); }
foreach ( array( 'contactpanda-business/v1', 'contactpanda_business_projects_list', 'contactpanda_business_tasks_search', 'contactpanda_business_import_stage', 'live_tasks_changed' ) as $contract ) if ( false === strpos( $mcp, $contract ) ) { fwrite( STDERR, "Missing MCP contract {$contract}.\n" ); exit( 1 ); }
foreach ( array( 'register_ability_hooks', 'wp_abilities_api_categories_init', 'wp_abilities_api_init', 'wp_register_ability_category', 'wp_register_ability', 'contactpanda-business/projects-list', 'contactpanda-business/project-get', 'contactpanda-business/tasks-search', 'contactpanda-business/import-stage', 'contactpanda-business/report-prepare' ) as $contract ) if ( false === strpos( $mcp, $contract ) ) { fwrite( STDERR, "Missing WordPress ability contract {$contract}.\n" ); exit( 1 ); }
if ( false === strpos( $main, 'ContactPanda_Business_MCP::register_ability_hooks();' ) ) { fwrite( STDERR, "Business must register ability hooks during plugin loading.\n" ); exit( 1 ); }
if ( false !== strpos( $projects, 'DROP TABLE' ) ) { fwrite( STDERR, "Business must not destructively drop tables.\n" ); exit( 1 ); }
if ( false !== strpos( $schema, 'DROP TABLE' ) || false !== strpos( $imports, 'DROP TABLE' ) ) { fwrite( STDERR, "Business upgrades and imports must remain non-destructive.\n" ); exit( 1 ); }
if ( false !== strpos( $projects, 'cpb-list' ) || false !== strpos( $projects, 'data-cpb-view' ) ) { fwrite( STDERR, "The project board must not expose the removed list view.\n" ); exit( 1 ); }
echo "ContactPanda Business foundation checks passed.\n";
